// @ts-strict-ignore
import styles from "./rich-text.module.less";
import { documentToReactComponents as renderRichText, Options } from "@contentful/rich-text-react-renderer";
import { BLOCKS, MARKS, INLINES, Block, Inline } from "@contentful/rich-text-types";
import Link from "@/core/components/primitives/link/link";
import { PrimaryButtonLink } from "@/core/components/primitives/parks-button/parks-button";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";
import { insertIntoString, isNonEmptyArray, multipleClassNames } from "@/core/helpers";
import { ExistingThemes } from "../../../types";
import { useTranslation } from "react-i18next";

const InlineEntryHyperLink = ({
  node,
  next,
  references,
}: {
  node: Block | Inline;
  next: React.ReactNode;
  references?: Array<ReferenceType>;
}) => {
  const { t } = useTranslation();
  const reference = references?.find((reference) => reference.contentful_id === node.data.target?.sys?.id);

  if (!reference) {
    return undefined;
  }

  const slug =
    (reference as ContentPageLinkReference).slug ||
    (reference as LinkReference).internalLink?.slug ||
    (reference as CallToActionLink).callToActionUrl?.slug;
  const link = (reference as LinkReference).externalUrl || (reference as CallToActionLink).externalLink;

  if (!slug && !link) {
    return undefined;
  }

  const title = isNonEmptyArray(next)
    ? (next[0] as string)
    : (reference as LinkReference | ContentPageLinkReference).title || t("toPage");

  return <Link internalLink={slug} externalLink={link} title={title} />;
};

const renderBlockEmbeddedEntry = (node: Block | Inline, next: React.ReactNode, references?: Array<ReferenceType>) => {
  const blockProps = node?.data?.target;
  const blockType = blockProps?.__typename || node?.data?.target?.sys?.type;

  switch (blockType) {
    case "ContentfulRichTextFeature": {
      return <RichTextFeature {...blockProps} />;
    }
    case "Link":
    case "ContentfulLink": {
      const linkFromBlock = blockProps?.internalLink?.slug || blockProps?.externalUrl;
      const maybeReference = references?.find((reference) => reference.contentful_id === blockProps?.sys?.id) as
        | LinkReference
        | CallToActionLink;
      const linkFromReference =
        (maybeReference as LinkReference)?.internalLink?.slug ||
        (maybeReference as CallToActionLink)?.callToActionUrl?.slug ||
        (maybeReference as LinkReference)?.externalUrl ||
        (maybeReference as CallToActionLink)?.externalLink;

      const link = linkFromBlock || linkFromReference;
      const label = blockProps?.title || maybeReference?.title;
      if (!link || !label) {
        return undefined;
      }
      return (
        <PrimaryButtonLink
          label={label}
          isFullWidth={true}
          url={link}
          {...blockProps}
          className={styles.primaryButtonLink}
        />
      );
    }
    default: {
      console.warn("WARNING: Unsupported block type in rich text renderer: ", blockType);
      return undefined;
    }
  }
};

const getOptions = (references?: Array<ReferenceType>) => {
  return {
    renderNode: {
      [INLINES.EMBEDDED_ENTRY]: (node, next) => {
        return <InlineEntryHyperLink node={node} next={next} references={references} />;
      },
      [INLINES.HYPERLINK]: (node, next) => {
        const uri: string = node?.data?.uri;
        return uri ? <a href={uri}>{next}</a> : <>{next}</>;
      },
      [INLINES.ENTRY_HYPERLINK]: (node, next) => {
        return <InlineEntryHyperLink node={node} next={next} references={references} />;
      },
      [INLINES.ASSET_HYPERLINK]: (node, next) => {
        const ref = references?.find((ref) => ref.contentful_id === node.data.target?.sys?.id);
        if (!ref || ref.__typename !== "ContentfulAsset") {
          return next;
        }
        const url = ref.file?.url;
        return url ? (
          <a href={url} target="_blank" rel="noreferrer">
            {next}
          </a>
        ) : (
          <>{next}</>
        );
      },
      [BLOCKS.EMBEDDED_ENTRY]: (node, next) => {
        return renderBlockEmbeddedEntry(node, next, references);
      },
      [BLOCKS.EMBEDDED_ASSET]: (node, next) => {
        const ref = references?.find((ref) => ref.contentful_id === node.data.target?.sys?.id);
        if (!ref || ref.__typename !== "ContentfulAsset") {
          return next;
        }
        const fileUrl = ref.file?.url;
        const fileContentType = ref.file?.contentType;
        const title = ref.title;

        // all common image MIME types start with "image", including JPEG, PNG, WEBP, GIF, and SVG
        if (!fileContentType?.includes("image") || !fileUrl) {
          return next;
        }
        return <img className={styles.image} src={fileUrl} alt={title} />;
      },
      [BLOCKS.HEADING_1]: (node, next) => <h1>{next}</h1>,
      [BLOCKS.HEADING_2]: (node, next) => <h2>{next}</h2>,
      [BLOCKS.HEADING_3]: (node, next) => <h3>{next}</h3>,
      [BLOCKS.HEADING_4]: (node, next) => <h4>{next}</h4>,
      [BLOCKS.HEADING_5]: (node, next) => <h5>{next}</h5>,
      [BLOCKS.HEADING_6]: (node, next) => <h6>{next}</h6>,
      [BLOCKS.PARAGRAPH]: (node, next) => <p className="paragraph">{next}</p>,
      [BLOCKS.UL_LIST]: (node, next) => <ul className="ul-list">{next}</ul>,
      [BLOCKS.LIST_ITEM]: (node, next) => (
        <li className={multipleClassNames("ul-list-item", styles.ulListItem)}>{next}</li>
      ),
      [BLOCKS.QUOTE]: (node, next) => <blockquote className="blockquote">{next}</blockquote>,
      [BLOCKS.HR]: (node, next) => <hr className="hr" />,
    },
    renderMark: {
      [MARKS.BOLD]: (text) => <b className="bold">{text}</b>,
      [MARKS.ITALIC]: (text) => <i className="italic">{text}</i>,
      [MARKS.UNDERLINE]: (text) => <u className="underline">{text}</u>,
      [MARKS.CODE]: (text) => <code className="code">{text}</code>,
    },
    renderText: (text) => {
      return text.split("\n").reduce((children, textSegment, index) => {
        return [...children, index > 0 && <br key={index} />, textSegment];
      }, []);
    },
  } satisfies Options;
};

/** VMH Specific */
export type CallToActionLink = {
  __typename: "ContentfulCallToActionBlock"; // VMH specific link-block
  contentful_id: string;
  title: string;
  callToActionUrl?: {
    slug: string;
  };
  externalLink?: string;
};

export type LinkReference = {
  __typename: "ContentfulLink" | "Link"; // These might differ between sites, so we allow both here
  contentful_id: string;
  title: string;
  internalLink?: {
    slug: string;
  };
  externalUrl?: string;
};

export type ContentPageLinkReference = {
  __typename: "ContentfulContentPage";
  contentful_id: string;
  title: string;
  slug: string;
};

export type ContentfulAssetReference = {
  __typename: "ContentfulAsset";
  contentful_id: string;
  title: string;
  file: {
    url: string;
    contentType: string;
  };
};

export type ReferenceType = LinkReference | ContentPageLinkReference | ContentfulAssetReference | CallToActionLink; //In the future we could support more reference types

export type RichTextType = {
  raw: string;
  references?: Array<ReferenceType>;
};

export type RichTextProps = {
  richText: RichTextType;
  replacementArgs?: string[];
  componentTheme?: ExistingThemes;
};

export const injectReplacementToRichText = (parsed: any, args: string[]) => {
  const replaced = {
    ...parsed,
    content: parsed.content.map((item) => ({
      ...item,
      content: item.content.map((item) => {
        if (item.nodeType === "text" && item.value.includes("{0}")) {
          return { ...item, value: insertIntoString(item.value, args) };
        } else {
          return item;
        }
      }),
    })),
  };
  return replaced;
};

const RichText = ({ richText, replacementArgs, componentTheme }: RichTextProps) => {
  if (!richText || !richText.raw) {
    return null;
  }

  const options = getOptions(richText.references);

  try {
    const parsed = JSON.parse(richText.raw);
    const richTextToRender = replacementArgs ? injectReplacementToRichText(parsed, replacementArgs) : parsed;
    return (
      <div data-has-theme={!!componentTheme} className={`${styles.richTextWrapper} ${componentTheme}`}>
        {renderRichText(richTextToRender, options)}
      </div>
    );
  } catch {
    return null;
  }
};

const RichTextExpandableText = ({ expandableRichText }: { expandableRichText: RichTextType }) => {
  return (
    <div className={styles.wrapper}>
      <ExpandContent>
        <RichText richText={expandableRichText} />
      </ExpandContent>
    </div>
  );
};

const RichTextFeature = (props: { featureType: string; expandTextBody: RichTextType }) => {
  const getComponentForFeatureType = (featureType: string) => {
    switch (featureType) {
      case "Expandable Text": {
        const expandTextBody = props?.expandTextBody;
        return <RichTextExpandableText expandableRichText={expandTextBody} />;
      }
      default: {
        return <></>;
      }
    }
  };

  return getComponentForFeatureType(props.featureType);
};

export default RichText;
